TCC.QUESTIONS = {
  sql: [
    { id: 'sql-01', level: 'easy',
      prompt: 'Which clause filters rows before they are grouped?',
      options: ['HAVING', 'WHERE', 'ORDER BY', 'GROUP BY'], answer: 1,
      hint: 'One clause works on individual rows, the other on groups.',
      explain: 'WHERE filters individual rows before GROUP BY runs. HAVING filters the groups afterwards.' },
    { id: 'sql-02', level: 'easy',
      prompt: 'The customers table has 10 rows, and 3 of them have a NULL email. What does this query return?',
      code: { lang: 'sql', file: 'query.sql', text: 'SELECT COUNT(*), COUNT(email)\nFROM customers;' },
      options: ['10, 10', '7, 7', '10, 7', '7, 10'], answer: 2,
      hint: 'COUNT(column) behaves differently from COUNT(*) when values are missing.',
      explain: 'COUNT(*) counts every row (10). COUNT(email) skips NULLs, so it returns 7.' },
    { id: 'sql-03', level: 'medium',
      prompt: 'Which query finds customers who have never placed an order?',
      code: { lang: 'sql', file: 'schema.sql', text: '-- customers(id, name)   orders(id, customer_id, total)' },
      options: [
        'SELECT c.name FROM customers c INNER JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL',
        'SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL',
        'SELECT c.name FROM customers c CROSS JOIN orders o WHERE o.id IS NULL',
        'SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id = NULL'
      ], answer: 1,
      hint: 'Which join keeps rows that have no match?',
      explain: 'A LEFT JOIN keeps every customer, and customers with no orders get NULL order columns. Filtering on o.id IS NULL leaves just those customers. An INNER JOIN drops them altogether.' },
    { id: 'sql-04', level: 'medium',
      prompt: 'This query is meant to find employees with no manager, but it returns no rows. Why?',
      code: { lang: 'sql', file: 'query.sql', text: 'SELECT name\nFROM employees\nWHERE manager_id = NULL;' },
      options: [
        'NULL must be written in lower case',
        'Comparing anything to NULL with = gives UNKNOWN, never TRUE; use IS NULL',
        'manager_id needs to be cast to text first',
        'WHERE cannot be used on columns that allow NULL'
      ], answer: 1,
      hint: 'NULL means "unknown". Is unknown equal to unknown?',
      explain: 'Any comparison with NULL using = or <> evaluates to UNKNOWN, so WHERE never keeps the row. Write WHERE manager_id IS NULL.' },
    { id: 'sql-05', level: 'medium',
      prompt: 'Which query lists departments that have more than 5 staff?',
      options: [
        'SELECT department FROM employees WHERE COUNT(*) > 5 GROUP BY department',
        'SELECT department FROM employees GROUP BY department HAVING COUNT(*) > 5',
        'SELECT department FROM employees GROUP BY department WHERE COUNT(*) > 5',
        'SELECT department, COUNT(*) > 5 FROM employees'
      ], answer: 1,
      hint: 'Aggregates such as COUNT(*) can’t be used in WHERE.',
      explain: 'A condition on an aggregate filters groups, so it belongs in HAVING, which comes after GROUP BY.' },
    { id: 'sql-06', level: 'medium',
      prompt: 'What is the difference between UNION and UNION ALL?',
      options: [
        'UNION removes duplicate rows; UNION ALL keeps them',
        'UNION ALL removes duplicate rows; UNION keeps them',
        'UNION needs the same column names; UNION ALL does not',
        'There is no difference'
      ], answer: 0,
      hint: 'One of them has to do extra work to compare rows.',
      explain: 'UNION removes duplicates, which needs a sort or hash step. UNION ALL appends the results as they are and is usually faster.' },
    { id: 'sql-07', level: 'hard',
      prompt: 'Scores are 90, 90 and 80. Which function returns 1, 1, 2 when ordering by score DESC?',
      code: { lang: 'sql', file: 'query.sql', text: 'SELECT name, score,\n       ???() OVER (ORDER BY score DESC) AS pos\nFROM results;' },
      options: ['ROW_NUMBER', 'RANK', 'DENSE_RANK', 'NTILE'], answer: 2,
      hint: 'RANK would give 1, 1, 3.',
      explain: 'DENSE_RANK gives tied rows the same rank and leaves no gaps: 1, 1, 2. RANK skips a number after a tie (1, 1, 3). ROW_NUMBER is always unique (1, 2, 3).' },
    { id: 'sql-08', level: 'hard',
      prompt: 'Why does this query fail in most databases?',
      code: { lang: 'sql', file: 'query.sql', text: 'SELECT price * qty AS revenue\nFROM order_lines\nWHERE revenue > 100;' },
      options: [
        'You can’t multiply two columns in SELECT',
        'WHERE is evaluated before SELECT, so the alias doesn’t exist yet',
        'Aliases must be written in quotes',
        'The comparison needs to be inside HAVING'
      ], answer: 1,
      hint: 'Think about the logical order: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.',
      explain: 'SELECT is processed after WHERE, so the alias revenue isn’t defined yet when WHERE runs. Repeat the expression (WHERE price * qty > 100) or use a subquery or CTE. ORDER BY runs last, so it can use the alias.' }
  ],

  powerbi: [
    { id: 'pbi-01', level: 'easy',
      prompt: 'Which language does Power Query use behind the scenes?',
      options: ['DAX', 'M', 'Python', 'SQL'], answer: 1,
      hint: 'You see it in the Advanced Editor.',
      explain: 'Every Power Query step is written in M, a functional language. DAX is for measures and calculated columns once the data is in the model.' },
    { id: 'pbi-02', level: 'easy',
      prompt: 'Which visual is usually best for showing a trend over time?',
      options: ['Pie chart', 'Line chart', 'Card', 'Treemap'], answer: 1,
      hint: 'Time runs naturally along an axis.',
      explain: 'A line chart with time on the x-axis shows direction, seasonality and change most clearly.' },
    { id: 'pbi-03', level: 'easy',
      prompt: 'Where do you create and manage relationships between tables?',
      options: ['Report view', 'Table view', 'Model view', 'Power Query editor'], answer: 2,
      hint: 'It shows tables as boxes joined by lines.',
      explain: 'Model view shows the tables in your model and lets you draw and edit relationships, cardinality and cross-filter direction.' },
    { id: 'pbi-04', level: 'medium',
      prompt: 'What is the default cross-filter direction of a one-to-many relationship?',
      options: ['Both', 'Single (from the one side to the many side)', 'None', 'Single (from the many side to the one side)'], answer: 1,
      hint: 'Dimensions filter facts.',
      explain: 'By default, filters flow from the one side (for example Product) to the many side (Sales). Bidirectional filtering is possible but can cause ambiguity and slow queries.' },
    { id: 'pbi-05', level: 'medium',
      prompt: 'Where is the best place to remove columns you don’t need?',
      options: ['Hide them in Report view', 'Remove them in Power Query before loading', 'Delete the visuals that use them', 'Set their data type to Text'], answer: 1,
      hint: 'Hidden columns still take up memory.',
      explain: 'Columns removed in Power Query never get loaded, which shrinks the model and speeds up refresh. Hidden columns are still stored.' },
    { id: 'pbi-06', level: 'medium',
      prompt: 'How is row-level security (RLS) defined in Power BI Desktop?',
      options: ['With roles that contain DAX filter expressions', 'By hiding pages', 'With Power Query parameters', 'By setting workspace permissions only'], answer: 0,
      hint: 'Modeling → Manage roles.',
      explain: 'You create roles with DAX table filters (for example [Region] = "North"), then assign users to those roles in the Power BI service.' },
    { id: 'pbi-07', level: 'hard',
      prompt: 'Sales has OrderDate (active) and ShipDate (inactive) relationships to the Date table. How do you write a measure by ship date?',
      code: { lang: 'dax', file: 'measure.dax', text: 'Sales by Ship Date =\nCALCULATE(\n    [Total Sales],\n    ???\n)' },
      options: [
        "USERELATIONSHIP( Sales[ShipDate], 'Date'[Date] )",
        "RELATED( Sales[ShipDate] )",
        "CROSSFILTER( Sales[ShipDate], 'Date'[Date], Both )",
        "TREATAS( Sales[ShipDate] )"
      ], answer: 0,
      hint: 'You need to switch on an inactive relationship for this one calculation.',
      explain: 'USERELATIONSHIP inside CALCULATE turns on the inactive relationship just for that calculation, so you don’t need a second Date table.' },
    { id: 'pbi-08', level: 'hard',
      prompt: 'Which is evaluated at query time, in the current filter context?',
      options: ['A calculated column', 'A measure', 'A calculated table', 'A Power Query custom column'], answer: 1,
      hint: 'One of them changes when you click a slicer.',
      explain: 'Measures are calculated on demand for each visual and filter. Calculated columns and tables are computed at refresh and stored in the model.' }
  ],

  excel: [
    { id: 'xl-01', level: 'easy',
      prompt: 'A1 = 2, A2 = 4 and A3 = "x" (text). What does this return?',
      code: { lang: 'excel', file: 'formula', text: '=SUM(A1:A3)' },
      options: ['#VALUE!', '6', '0', '#N/A'], answer: 1,
      hint: 'SUM over a range is forgiving.',
      explain: 'SUM ignores text in a referenced range, so it returns 2 + 4 = 6. =A1+A2+A3 would return #VALUE! instead.' },
    { id: 'xl-02', level: 'easy',
      prompt: 'Which reference keeps both the column and the row fixed when you copy the formula?',
      options: ['A1', '$A1', 'A$1', '$A$1'], answer: 3,
      hint: 'The $ sign locks whatever comes right after it.',
      explain: '$A$1 is fully absolute. $A1 locks only the column, and A$1 locks only the row.' },
    { id: 'xl-03', level: 'easy',
      prompt: 'Which function removes extra spaces from the start and end of text?',
      options: ['CLEAN', 'TRIM', 'SUBSTITUTE', 'PROPER'], answer: 1,
      hint: 'Think of trimming a hedge.',
      explain: 'TRIM removes leading and trailing spaces and turns repeated spaces between words into one. CLEAN removes non-printing characters.' },
    { id: 'xl-04', level: 'medium',
      prompt: 'What is the default match type when you leave out the last argument of VLOOKUP?',
      code: { lang: 'excel', file: 'formula', text: '=VLOOKUP(E2, A2:C100, 3)' },
      options: ['Exact match', 'Approximate match', 'Wildcard match', 'It returns an error'], answer: 1,
      hint: 'This is one of the most common VLOOKUP mistakes.',
      explain: 'When range_lookup is left out it defaults to TRUE (approximate match), which needs sorted data and can quietly return the wrong row. Pass FALSE, or use XLOOKUP, which matches exactly by default.' },
    { id: 'xl-05', level: 'medium',
      prompt: 'What does this formula count?',
      code: { lang: 'excel', file: 'formula', text: '=COUNTIFS(A:A, "North", B:B, ">100")' },
      options: [
        'Rows where A is "North" OR B is over 100',
        'Rows where A is "North" AND B is over 100',
        'The sum of B where A is "North"',
        'Cells in A and B that are not empty'
      ], answer: 1,
      hint: 'Each extra pair of arguments adds another condition.',
      explain: 'COUNTIFS counts the rows where every condition is true, so here region = North AND value > 100.' },
    { id: 'xl-06', level: 'medium',
      prompt: 'In a pivot table, how do you show each region as a share of the total?',
      options: ['Show Values As → % of Grand Total', 'Summarize Values By → Average', 'Add a calculated item', 'Sort by value, largest to smallest'], answer: 0,
      hint: 'Right-click a value in the pivot.',
      explain: 'Show Values As → % of Grand Total (or % of Column Total) turns each value into its share without any extra formulas.' },
    { id: 'xl-07', level: 'hard',
      prompt: 'What does this formula return?',
      code: { lang: 'excel', file: 'formula', text: '=INDEX(B2:B10, MATCH("Kim", A2:A10, 0))' },
      options: [
        'The row number where "Kim" appears',
        'The value in column B on the same row as "Kim" in column A',
        'TRUE if "Kim" is in A2:A10',
        'The number of times "Kim" appears'
      ], answer: 1,
      hint: 'MATCH finds the position, and INDEX fetches the value at that position.',
      explain: 'MATCH(..., 0) returns Kim’s position in A2:A10 using an exact match. INDEX then returns the value at the same position in B2:B10. It’s a flexible lookup that can look left as well as right.' },
    { id: 'xl-08', level: 'hard',
      prompt: 'What does this formula return?',
      code: { lang: 'excel', file: 'formula', text: '=IFERROR(1/0, "n/a")' },
      options: ['#DIV/0!', '0', '"n/a"', 'FALSE'], answer: 2,
      hint: 'What would 1/0 be on its own?',
      explain: '1/0 gives #DIV/0!. IFERROR catches any error and returns the fallback, so the result is "n/a".' }
  ],

  dax: [
    { id: 'dax-01', level: 'easy',
      prompt: 'Which function works through a table row by row, evaluating an expression for each row before adding the results?',
      options: ['SUM', 'SUMX', 'TOTALYTD', 'CALCULATE'], answer: 1,
      hint: 'Functions that end in X are iterators.',
      explain: 'SUMX(Table, Expression) evaluates the expression for each row, for example Sales[Qty] * Sales[Price], then adds the results. SUM can only add up a single column.' },
    { id: 'dax-02', level: 'easy',
      prompt: 'Why use DIVIDE instead of the / operator?',
      code: { lang: 'dax', file: 'measure.dax', text: 'Margin % = DIVIDE( [Profit], [Revenue] )' },
      options: [
        'It is the only way to divide in DAX',
        'It handles division by zero safely, returning BLANK or an alternate result',
        'It always rounds to two decimals',
        'It ignores filter context'
      ], answer: 1,
      hint: 'What happens when Revenue is 0?',
      explain: 'DIVIDE returns BLANK (or the optional third argument) when the denominator is 0, so visuals don’t show errors.' },
    { id: 'dax-03', level: 'medium',
      prompt: 'What does CALCULATE change?',
      options: ['The row context', 'The filter context', 'The data type of a column', 'The order of rows'], answer: 1,
      hint: 'Its extra arguments are called filter arguments.',
      explain: 'CALCULATE evaluates an expression in a modified filter context. It adds, replaces or removes filters using its filter arguments.' },
    { id: 'dax-04', level: 'medium',
      prompt: 'What is one benefit of VAR … RETURN in a measure?',
      code: { lang: 'dax', file: 'measure.dax', text: 'Growth % =\nVAR Curr = [Total Sales]\nVAR Prev = [Sales LY]\nRETURN DIVIDE( Curr - Prev, Prev )' },
      options: [
        'Variables are recalculated each time they are used',
        'Each variable is evaluated once, which makes the code faster and easier to read',
        'Variables are stored in the model like columns',
        'Variables ignore filters'
      ], answer: 1,
      hint: 'Prev is used twice in this measure.',
      explain: 'A variable is evaluated once, in the context where it is defined, and the result is reused. Without it, [Sales LY] would be calculated twice.' },
    { id: 'dax-05', level: 'hard',
      prompt: 'Which measure returns total sales for the same period last year?',
      code: { lang: 'dax', file: 'model', text: "// Sales[Amount], 'Date'[Date] (marked as date table)" },
      options: [
        "CALCULATE( SUM( Sales[Amount] ), SAMEPERIODLASTYEAR( 'Date'[Date] ) )",
        "SUM( Sales[Amount] ) - 365",
        "CALCULATE( SUM( Sales[Amount] ), YEAR( 'Date'[Date] ) - 1 )",
        "SAMEPERIODLASTYEAR( SUM( Sales[Amount] ) )"
      ], answer: 0,
      hint: 'Time intelligence functions return a table of dates that CALCULATE uses as a filter.',
      explain: 'SAMEPERIODLASTYEAR returns the current dates moved back one year. CALCULATE then uses them as the filter for the sum.' },
    { id: 'dax-06', level: 'hard',
      prompt: 'Which measure gives each product’s share of total sales, ignoring the product filter?',
      options: [
        'DIVIDE( [Sales], CALCULATE( [Sales], ALL( Product ) ) )',
        'DIVIDE( [Sales], SUM( Sales[Amount] ) )',
        'DIVIDE( [Sales], FILTER( Product, TRUE() ) )',
        'DIVIDE( [Sales], [Sales] )'
      ], answer: 0,
      hint: 'The denominator needs to remove the filter coming from each product row.',
      explain: 'ALL(Product) removes the product filter inside CALCULATE, so the denominator is the total for all products while the numerator stays per product.' },
    { id: 'dax-07', level: 'hard',
      prompt: 'When does context transition happen?',
      options: [
        'Whenever a measure is placed on a card visual',
        'When CALCULATE (or a measure reference) runs inside a row context, turning that row into a filter',
        'When a relationship is set to bidirectional',
        'When you use VAR'
      ], answer: 1,
      hint: 'Every measure reference is wrapped in an implicit CALCULATE.',
      explain: 'Inside a row context, such as a calculated column or an iterator, CALCULATE turns the current row into an equivalent filter context. That’s why a measure used in a calculated column gives a different result on each row.' },
    { id: 'dax-08', level: 'medium',
      prompt: 'Which measure gives year-to-date sales?',
      options: [
        "TOTALYTD( [Total Sales], 'Date'[Date] )",
        "SUM( [Total Sales] )",
        "YEAR( [Total Sales] )",
        "CALCULATE( [Total Sales], ALL( 'Date' ) )"
      ], answer: 0,
      hint: 'There is a dedicated time intelligence function for this.',
      explain: "TOTALYTD adds up the measure from the start of the year to the last date in the current filter context. It’s shorthand for CALCULATE( [Total Sales], DATESYTD( 'Date'[Date] ) )." }
  ],

  model: [
    { id: 'mdl-01', level: 'easy',
      prompt: 'In a star schema, which table sits in the middle and stores measurable events?',
      options: ['Dimension table', 'Fact table', 'Bridge table', 'Lookup table'], answer: 1,
      hint: 'Sales, orders, clicks…',
      explain: 'Fact tables store events with numeric measures (amount, quantity) plus foreign keys to the dimensions around them.' },
    { id: 'mdl-02', level: 'easy',
      prompt: 'What does a dimension table mainly hold?',
      options: ['Descriptive attributes used to filter and group', 'Transaction amounts', 'Only dates', 'Pre-calculated totals'], answer: 0,
      hint: 'Think of the "by" in "sales by region".',
      explain: 'Dimensions (Customer, Product, Date) describe the who, what, where and when that you slice facts by.' },
    { id: 'mdl-03', level: 'medium',
      prompt: 'What is the cardinality between Customer and Orders?',
      options: ['One-to-one', 'One-to-many', 'Many-to-many', 'Many-to-one from Customer to Orders'], answer: 1,
      hint: 'Can one customer place several orders? Can one order belong to several customers?',
      explain: 'One customer can have many orders, and each order belongs to one customer, so the relationship is one-to-many.' },
    { id: 'mdl-04', level: 'medium',
      prompt: 'What is a surrogate key?',
      options: [
        'A key copied from the source system, such as an email address',
        'A meaningless integer created by the warehouse to identify a row',
        'A key that combines every column',
        'A backup copy of the primary key'
      ], answer: 1,
      hint: 'It has no business meaning.',
      explain: 'Surrogate keys are simple integers created in the model. They stay stable when source IDs change and let you keep history (see SCD type 2).' },
    { id: 'mdl-05', level: 'medium',
      prompt: 'Students can take many courses and courses have many students. How do you model this?',
      options: ['Put a course list in a text column on Students', 'Add a bridge table such as Enrolments(student_id, course_id)', 'Merge both tables into one', 'Use a one-to-one relationship'], answer: 1,
      hint: 'Break one many-to-many into two one-to-many relationships.',
      explain: 'A bridge (junction) table holds one row per student–course pair, which turns the many-to-many into two one-to-many relationships.' },
    { id: 'mdl-06', level: 'hard',
      prompt: 'How does a type 2 slowly changing dimension keep history when a customer moves city?',
      options: [
        'It overwrites the city',
        'It adds a new row with a new surrogate key and valid-from / valid-to dates',
        'It adds a "previous city" column',
        'It deletes the old customer'
      ], answer: 1,
      hint: 'Old facts should still point to the old city.',
      explain: 'SCD type 2 closes the old row (valid_to, is_current = 0) and inserts a new one. Existing facts keep pointing to the old version, so history stays correct. Type 1 overwrites; type 3 adds a column.' },
    { id: 'mdl-07', level: 'hard',
      prompt: 'Why is a star schema usually preferred over a snowflake in Power BI?',
      options: [
        'Snowflakes can’t have relationships',
        'Fewer relationships make filters simpler and faster and the model easier to use',
        'Star schemas use less storage in every case',
        'Power BI can’t import normalised tables'
      ], answer: 1,
      hint: 'Every extra hop is another relationship that filters have to travel through.',
      explain: 'Flattening each dimension into one table means shorter filter paths, simpler DAX and a cleaner field list. The VertiPaq engine compresses the repeated values well.' }
  ]
};
